const mode = String($env.WEBHOOK_VERIFY_SIGNATURE || 'false').toLowerCase();
const passthrough = (verified, m) => [{ json: Object.assign({ verified, mode: m }, $input.first().json) }];
if (mode === 'false') { return passthrough(true, 'disabled'); }
const secret = $env.META_APP_SECRET || '';
const headers = $input.first().json.headers || {};
const signature = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';
const rawBody = JSON.stringify($input.first().json.body);
if (!secret) { return passthrough(false, 'missing_secret'); }
const run = async () => { try { const encoder = new TextEncoder(); const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']); const sig = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody)); const hex = Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join(''); return passthrough(signature === 'sha256=' + hex, 'enabled'); } catch (e) { return passthrough(false, 'crypto_unavailable'); } };
return run();

// Normaliza el payload; los eventos no-mensaje (status, tipos raros, propio negocio) terminan en silencio (return []).
const payload = $input.first().json;
const businessPhone = ($env.WHATSAPP_BUSINESS_PHONE || '').replace(/\D/g, '');
for (const entry of payload.body.entry || payload.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    if (value.messages && value.messages.length > 0) {
      const msg = value.messages[0];
      const from = String(msg.from || '').replace(/\D/g, '');
      if (businessPhone && from === businessPhone) { return []; }
      const hasText = msg.text && msg.text.body;
      if (msg.type && msg.type !== 'text' && !hasText) {
      const label = { image: '🖼️ [El cliente envio una imagen]', audio: '🎤 [El cliente envio un audio]', video: '🎬 [El cliente envio un video]', document: '📄 [El cliente envio un documento]' }[msg.type] || '📎 [El cliente envio un adjunto]';
      return [{ json: { valid: true, contact_phone: from, message_text: label, message_id: msg.id || '', timestamp: msg.timestamp || '', type: msg.type || 'media' } }];
    }
      if (!hasText) { return []; }
      return [{ json: { valid: true, contact_phone: from, message_text: String(msg.text.body).slice(0, 2000), message_id: msg.id || '', timestamp: msg.timestamp || '', type: msg.type || 'text' } }];
    }
    if (value.statuses && value.statuses.length > 0) { return []; }
  }
}
return [];

// Encuentra la fila del contacto en cualquier forma de respuesta (array, body, anidado).
const findRow = (x) => {
  if (Array.isArray(x)) { for (const it of x) { const f = findRow(it); if (f) return f; } return null; }
  if (x && typeof x === 'object') {
    if (x.id && (x.telefono || x.tenant_id)) return x;
    for (const v of Object.values(x)) { const f = findRow(v); if (f) return f; }
  }
  return null;
};
const row = findRow($json) || {};
if (!row.id) { throw new Error('UPSERT-FALLO: ' + JSON.stringify($json).slice(0, 300)); }
return [{ json: { contacto_id: row.id, tenant_id: row.tenant_id || null } }];

const text = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '');
const clean = text.replace(/\[DERIVAR\]/gi, '').replace(/\[LEAD[^\]]*\]/gi, '').trim().slice(0, 4000);
const userText = ($('Normalizar Mensaje').item.json.message_text || '').toLowerCase();
const HUMAN_RE = /(hablar con (alguien|un humano|una persona|un asesor|alguien real)|asesor humano|persona real|no me convence|no me gusta|queja|quejarme|molest|frustrad|insatisfech|ineficiente|mal servicio|estafa|llamar|llamada|representante|me canse|aburrid)/i;
const LEAD_RE = /(agendar|cita|reuni[oó]n|diagn[oó]stic|cotiz|propuest|presupuest|quiero (comprar|contratar|empezar)|me interesa)/i;
const PEDIDO_RE = /(pedido|quiero (pedir|ordenar|encargar|reservar)|me llevo|hacer (un|mi) pedido|domicilio|delivery|a domicilio|talla|disponibilidad)/i;
const PAGO_RE = /(pagar|pago|transferenc|nequi|daviplata|davi|tarjeta|bono|cup[oó]n|promoci[oó]n|adelanto|consignaci[oó]n)/i;
const marker = (text.match(/\[LEAD ([^\]]*)\]/i) || [null, ''])[1];
let evento = 'none';
if (/\[DERIVAR\]/i.test(text) || HUMAN_RE.test(userText)) evento = 'derivar';
else if (marker || LEAD_RE.test(userText)) evento = 'lead';
else if (PAGO_RE.test(userText)) evento = 'pago';
else if (PEDIDO_RE.test(userText)) evento = 'pedido';
return [{ json: { raw: text, clean, needs_human: evento === 'derivar', lead_marker: marker || (LEAD_RE.test(userText) ? 'cita' : ''), evento } }];

// Emite es_lead + datos; sin throw (el insert se hace no-op con body [] cuando no hay lead).
const lead = $('Extraer Respuesta').item.json.lead_marker || '';
const parts = lead ? String(lead).split('|') : [];
return [{ json: {
  es_lead: Boolean(lead),
  nombre: (parts[0] || '').trim(),
  telefono: $('Normalizar Mensaje').item.json.contact_phone,
  interes: (parts[2] || parts[0] || '').trim()
} }];

const extra = $('Extraer Respuesta').item.json;
const phone = $('Normalizar Mensaje').item.json.contact_phone;
const evento = extra.evento || 'none';
const emojis = { derivar: '🚨 DERIVAR', lead: '📅 LEAD', pedido: '🛒 PEDIDO', pago: '💰 PAGO' };
const notificar = evento !== 'none';
const texto = notificar ? (emojis[evento] + ': ' + phone + ' | ' + extra.clean) : '';
return [{ json: { notificar, texto } }];
